"""Conservative, hysteretic closed-loop target navigation policy."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, target confirmation, and hysteretic steering/search."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    last_action = memory.get("last_action")
    action_age = int(memory.get("action_age", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        """Record a bounded action hysteresis state and return the decision."""
        nonlocal last_action, action_age
        if action == last_action:
            action_age += 1
        else:
            action_age = 0
        memory["last_action"] = action
        memory["action_age"] = min(action_age, 4)
        memory["state"] = next_state
        return action, confidence, memory

    # Hard safety gate.
    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "REACQUIRE", "VERIFY"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            # Keep one scan direction for two frames to avoid oscillation.
            if lost_steps % 2 == 0:
                scan_direction = (
                    "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
                )
            memory["scan_direction"] = scan_direction
            return emit(scan_direction, 0.76, "SEARCH")
        memory["scan_direction"] = scan_direction
        return emit(scan_direction, 0.74, "SEARCH")

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if heading_error <= 15.0 and identity_confidence >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        if bearing < 0 and observation["corridor_left"]:
            return emit("VEER_LEFT", 0.87, "APPROACH")
        if bearing >= 0 and observation["corridor_right"]:
            return emit("VEER_RIGHT", 0.87, "APPROACH")
        return emit("STOP", 0.94, "STOPPED")

    # Use a deadband for efficient forward motion and hysteresis for turns.
    desired = "FORWARD"
    if bearing < -14.0 and observation["corridor_left"]:
        desired = "VEER_LEFT"
    elif bearing > 14.0 and observation["corridor_right"]:
        desired = "VEER_RIGHT"
    elif abs(bearing) > 24.0:
        if bearing < 0 and observation["corridor_left"]:
            desired = "VEER_LEFT"
        elif bearing > 0 and observation["corridor_right"]:
            desired = "VEER_RIGHT"

    if desired == "FORWARD" and not observation["corridor_center"]:
        if bearing < 0 and observation["corridor_left"]:
            desired = "VEER_LEFT"
        elif bearing > 0 and observation["corridor_right"]:
            desired = "VEER_RIGHT"
        else:
            return emit("STOP", 0.98, "STOPPED")

    # Retain an established turn briefly when the bearing is near its boundary.
    if (
        last_action in {"VEER_LEFT", "VEER_RIGHT"}
        and desired == "FORWARD"
        and action_age < 1
    ):
        if (
            (last_action == "VEER_LEFT" and bearing < 5.0 and observation["corridor_left"])
            or (
                last_action == "VEER_RIGHT"
                and bearing > -5.0
                and observation["corridor_right"]
            )
        ):
            desired = last_action

    confidence = 0.90 if desired == "FORWARD" else 0.87
    return emit(desired, confidence, "APPROACH")


# EVOLVE-BLOCK-END
